window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76f511c320d5a5f4"]={"versions": [{"id": "FIG-76f511c320d5a5f4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von XML-Schema-Erzeugungsregeln im Rahmen der AUTOSAR XML Schema Production Rules (TPS_XMLSPR_00007). Das Diagramm veranschaulicht als Metamodell-Beispiel die Transformation eines UML-Enumeration-Typs in ein entsprechendes XML-Schema-Konstrukt (<code>xsd:simpleType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine einzelne UML-Klasse bzw. einen Enumerationstyp mit dem Stereotyp <code>«enumeration»</code> und dem Bezeichner <code>EnumerationInfoType</code>. Die Entität besitzt zwei Enumeration-Literale bzw. Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>data</code></li>\n<li><code>event</code></li>\n</ul>\n<p class=\"fig-p\">Beziehungen oder Assoziationen zu weiteren Metaklassen sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Fragment ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Auswertung erfolgt rein deklarativ im Rahmen des Schema-Generierungsprozesses: Für die Klasse mit dem Stereotyp <code>«enumeration»</code> wird ein <code>xsd:simpleType</code> mit einer <code>xsd:restriction</code> auf <code>xsd:string</code> erzeugt, dessen <code>xsd:enumeration</code>-Werte direkt aus den Attributnamen <code>data</code> und <code>event</code> abgeleitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Regel [TPS_XMLSPR_00007]. Für jede Metaklasse mit dem Stereotyp <code>«enumeration»</code> ist ein korrespondierender <code>xsd:simpleType</code> im XML-Schema anzulegen. Die Literalwerte (<code>data</code>, <code>event</code>) definieren den zulässigen Wertebereich im Schema (<code>xsd:enumeration value=\"...\"</code>). In AUTOSAR-XML-Instanzen (ARXML) dürfen als Elementinhalt ausschließlich die deklarierten String-Literale auftreten.</p>"}, {"id": "FIG-b86f3c5779e7bbcf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von XML-Schema-Erzeugungsregeln im Rahmen der AUTOSAR XML Schema Production Rules (TPS_XMLSPR_00007). Das Diagramm veranschaulicht als Metamodell-Beispiel die Transformation eines UML-Enumeration-Typs in ein entsprechendes XML-Schema-Konstrukt (<code>xsd:simpleType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine einzelne UML-Klasse bzw. einen Enumerationstyp mit dem Stereotyp <code>«enumeration»</code> und dem Bezeichner <code>EnumerationInfoType</code>. Die Entität besitzt zwei Enumeration-Literale bzw. Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>data</code></li>\n<li><code>event</code></li>\n</ul>\n<p class=\"fig-p\">Beziehungen oder Assoziationen zu weiteren Metaklassen sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Fragment ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Auswertung erfolgt rein deklarativ im Rahmen des Schema-Generierungsprozesses: Für die Klasse mit dem Stereotyp <code>«enumeration»</code> wird ein <code>xsd:simpleType</code> mit einer <code>xsd:restriction</code> auf <code>xsd:string</code> erzeugt, dessen <code>xsd:enumeration</code>-Werte direkt aus den Attributnamen <code>data</code> und <code>event</code> abgeleitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Regel [TPS_XMLSPR_00007]. Für jede Metaklasse mit dem Stereotyp <code>«enumeration»</code> ist ein korrespondierender <code>xsd:simpleType</code> im XML-Schema anzulegen. Die Literalwerte (<code>data</code>, <code>event</code>) definieren den zulässigen Wertebereich im Schema (<code>xsd:enumeration value=\"...\"</code>). In AUTOSAR-XML-Instanzen (ARXML) dürfen als Elementinhalt ausschließlich die deklarierten String-Literale auftreten.</p>"}, {"id": "FIG-52f72e27d9c60b32", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von XML-Schema-Erzeugungsregeln im Rahmen der AUTOSAR XML Schema Production Rules (TPS_XMLSPR_00007). Das Diagramm veranschaulicht als Metamodell-Beispiel die Transformation eines UML-Enumeration-Typs in ein entsprechendes XML-Schema-Konstrukt (<code>xsd:simpleType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine einzelne UML-Klasse bzw. einen Enumerationstyp mit dem Stereotyp <code>«enumeration»</code> und dem Bezeichner <code>EnumerationInfoType</code>. Die Entität besitzt zwei Enumeration-Literale bzw. Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>data</code></li>\n<li><code>event</code></li>\n</ul>\n<p class=\"fig-p\">Beziehungen oder Assoziationen zu weiteren Metaklassen sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Fragment ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Auswertung erfolgt rein deklarativ im Rahmen des Schema-Generierungsprozesses: Für die Klasse mit dem Stereotyp <code>«enumeration»</code> wird ein <code>xsd:simpleType</code> mit einer <code>xsd:restriction</code> auf <code>xsd:string</code> erzeugt, dessen <code>xsd:enumeration</code>-Werte direkt aus den Attributnamen <code>data</code> und <code>event</code> abgeleitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Regel [TPS_XMLSPR_00007]. Für jede Metaklasse mit dem Stereotyp <code>«enumeration»</code> ist ein korrespondierender <code>xsd:simpleType</code> im XML-Schema anzulegen. Die Literalwerte (<code>data</code>, <code>event</code>) definieren den zulässigen Wertebereich im Schema (<code>xsd:enumeration value=\"...\"</code>). In AUTOSAR-XML-Instanzen (ARXML) dürfen als Elementinhalt ausschließlich die deklarierten String-Literale auftreten.</p>"}], "trans": [{"from": "FIG-76f511c320d5a5f4", "to": "FIG-b86f3c5779e7bbcf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b86f3c5779e7bbcf", "to": "FIG-52f72e27d9c60b32", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
